import pandas as pd
import numpy as np

def quality_counts_fixed(df: pd.DataFrame) -> dict:
    ratio = df["reading"] / df["baseline"]
    missing_mask = df["reading"].isna() | df["baseline"].isna()
    missing = int(missing_mask.sum())
    undefined = int((~missing_mask & ratio.isna()).sum())
    return {"missing": missing, "undefined_ratio": undefined}

# Case 1: missing data
df_missing = pd.DataFrame({
    "reading": pd.Series([1.0, pd.NA, 1.0], dtype="Float64"),
    "baseline": pd.Series([pd.NA, 1.0, 1.0], dtype="Float64")
})
print(f"Missing data: {quality_counts_fixed(df_missing)}") # Expected: {'missing': 2, 'undefined_ratio': 0}

# Case 2: undefined ratio (0/0)
df_undefined = pd.DataFrame({
    "reading": pd.Series([0.0, 1.0], dtype="Float64"),
    "baseline": pd.Series([0.0, 1.0], dtype="Float64")
})
print(f"Undefined ratio: {quality_counts_fixed(df_undefined)}") # Expected: {'missing': 0, 'undefined_ratio': 1}

# Case 3: both
df_both = pd.DataFrame({
    "reading": pd.Series([pd.NA, 0.0, 1.0], dtype="Float64"),
    "baseline": pd.Series([1.0, 0.0, 1.0], dtype="Float64")
})
print(f"Both: {quality_counts_fixed(df_both)}") # Expected: {'missing': 1, 'undefined_ratio': 1}
EOF
